--!strict
local Profiles=require(script.Parent.Services.PlayerProfileService);local remotes=require(script.Parent.Services.RemoteService).Ensure();local allowed={MusicEnabled="boolean",SoundEnabled="boolean",ReducedEffects="boolean",ShowTutorialHints="boolean",ShowRankAbovePlayers="boolean",AutoOpenResults="boolean",UIScale="string"};local rate:{[Player]:number}={}
local function send(player:Player)local profile=Profiles.GetProfile(player);if profile then remotes.SettingsUpdated:FireClient(player,table.clone(profile.Settings))end end
remotes.RequestSettings.OnServerEvent:Connect(function(player)task.spawn(function()local deadline=os.clock()+10;while not Profiles.IsProfileLoaded(player)and os.clock()<deadline do task.wait(.2)end;send(player)end)end)
remotes.UpdateSettings.OnServerEvent:Connect(function(player,key,value)if typeof(key)~="string"or allowed[key]~=typeof(value)or os.clock()-(rate[player]or 0)<.15 then return end;if key=="UIScale"and not table.find({"Small","Normal","Large"},value)then return end;rate[player]=os.clock();if Profiles.UpdateValue(player,"Settings."..key,value)then send(player)end end)
